package e.e.a;
import java.io.*;import java.util.*;import android.content.*;import android.preference.PreferenceManager;
public class CacheCommentsTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception {PreferenceManager.prefs=(SharedPreferences)CacheDefaultTest.preferences(SharedPreferences.class);File root=new File(args[0]);root.mkdirs();CacheFolders.init(new Context(root,root));String folder=root.getAbsolutePath();String json="{\"threads\":[{\"comments\":[\""+String.join("",Collections.nCopies(10000,"example comment "))+"\"]}]}";
 CacheComments.save(folder,"sm1",json);check(!new File(root,"sm1.comments.gz").exists(),"online playback stores no comments");File marker=new File(root,"sm1.mp4");try(OutputStream out=new FileOutputStream(marker)){out.write(1);}CacheComments.save(folder,"sm1",json);File zip=new File(root,"sm1.comments.gz");check(zip.isFile()&&zip.length()<json.length()/10,"compression reduces repeated comments");check(json.equals(CacheComments.read(folder,"sm1")),"compressed comments survive roundtrip");File legacy=new File(root,"sm1.comments.json");try(OutputStream out=new FileOutputStream(legacy)){out.write(json.getBytes("UTF-8"));}long timestamp=946684800000L;check(zip.setLastModified(timestamp),"set compressed file time");CacheComments.clean(folder,new CacheFile(folder).listFiles());check(!legacy.exists()&&zip.lastModified()==timestamp,"valid compressed comments are not recompressed");try(OutputStream out=new FileOutputStream(legacy)){out.write(json.getBytes("UTF-8"));}try(OutputStream out=new FileOutputStream(zip)){out.write(0);}check(json.equals(CacheComments.read(folder,"sm1")),"corrupt compressed file falls back to legacy comments");CacheComments.clean(folder,new CacheFile(folder).listFiles());check(!legacy.exists()&&json.equals(CacheComments.read(folder,"sm1")),"legacy comments repair corrupt compressed file");File orphan=new File(root,"sm2.comments.json");try(OutputStream out=new FileOutputStream(orphan)){out.write(json.getBytes("UTF-8"));}check(!CacheComments.copyable(orphan),"orphan comments not copied");check(CacheComments.copyable(zip),"cached-video comments copied");CacheComments.clean(folder,new CacheFile(folder).listFiles());check(!orphan.exists()&&zip.exists(),"cleanup retains valid cache comments");marker.delete();CacheComments.clean(folder,new CacheFile(folder).listFiles());check(!zip.exists(),"removing video removes persistent comments");System.out.println("Comment compression, ownership, copy and cleanup: 11 checks passed");}
}
